import 'model_utils.dart';
class ConsultationModel { const ConsultationModel({required this.id,required this.studentId,required this.advisorId,required this.status,required this.createdAt,this.conversationId,this.note,this.rating}); final String id,studentId,advisorId; final ConsultationStatus status; final DateTime createdAt; final String? conversationId,note; final double? rating; factory ConsultationModel.fromFirestore(DocumentSnapshot<Map<String,Object?>> d)=>ConsultationModel(id:d.id,studentId:d['studentId'] as String,advisorId:d['advisorId'] as String,status:ConsultationStatus.values.byName(d['status'] as String),createdAt:dateFromValue(d['createdAt'])!,conversationId:d['conversationId'] as String?,note:d['note'] as String?,rating:(d['rating'] as num?)?.toDouble()); Map<String,Object?> toFirestore()=>{'studentId':studentId,'advisorId':advisorId,'status':status.value,'createdAt':Timestamp.fromDate(createdAt),'conversationId':conversationId,'note':note,'rating':rating}; }
